import{K as l,a as i,c as r,b as a,k as s,q as n,ac as c}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"Excel 进阶分析：数据模型、目标求解与方案比较","description":"理解 Power Pivot 表关系、DAX 度量值和计算列，使用目标求解、双变量方案表与规划求解思路，核对业务假设和模型边界。","frontmatter":{"title":"Excel 进阶分析：数据模型、目标求解与方案比较","description":"理解 Power Pivot 表关系、DAX 度量值和计算列，使用目标求解、双变量方案表与规划求解思路，核对业务假设和模型边界。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Excel 表格与数据分析","summary":"理解 Power Pivot 表关系、DAX 度量值和计算列，使用目标求解、双变量方案表与规划求解思路，核对业务假设和模型边界。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Excel Power Query 导入、清洗、合并与刷新","link":"/tools/office/excel/power-query"},"next":{"text":"Excel 打印、导出与工作簿交付","link":"/tools/office/excel/printing"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Excel Power Query 导入、清洗、合并与刷新","link":"/tools/office/excel/power-query"},"next":{"text":"Excel 打印、导出与工作簿交付","link":"/tools/office/excel/printing"}},"headers":[],"relativePath":"tools/office/excel/analysis.md","filePath":"tools/office/excel/analysis.md"}'),h={name:"tools/office/excel/analysis.md"},g=Object.assign(h,{setup(p){const t={path:"/tools/office/excel/analysis",app:"Excel",title:"反推达到利润目标所需的数量",steps:[{tab:"工作表区域",command:"单元格 B2:B6",setting:"B2=100；B3=60；B4=1000；B5=1",anchor:"walkthrough-1",surface:"area"},{tab:"数据",command:"单变量求解",setting:"目标单元格：B6；目标值：2000；可变单元格：B5",anchor:"walkthrough-2"},{tab:"数据",command:"单变量求解",setting:"单位成本改为 70；重新求解：数量 100",anchor:"walkthrough-3"}]};return(d,e)=>{const o=l("OfficeGuide");return i(),r("div",null,[e[0]||(e[0]=a("h1",{id:"excel-进阶分析-数据模型、目标求解与方案比较",tabindex:"-1"},[s("Excel 进阶分析：数据模型、目标求解与方案比较 "),a("a",{class:"header-anchor",href:"#excel-进阶分析-数据模型、目标求解与方案比较","aria-label":'Permalink to "Excel 进阶分析：数据模型、目标求解与方案比较"'},"​")],-1)),e[1]||(e[1]=a("p",null,"本篇分成两个场景：多张表如何共同分析，以及在明确计算模型后如何比较方案。先确保基础公式和透视表可靠，再引入模型；功能是否可用要按版本、平台和许可确认。",-1)),n(o,{guide:t}),e[2]||(e[2]=c(`<h2 id="model" tabindex="-1">什么时候使用数据模型 <a class="header-anchor" href="#model" aria-label="Permalink to &quot;什么时候使用数据模型 {#model}&quot;">​</a></h2><p>只有一张小明细表时，普通透视表通常足够。订单、产品、部门分别维护且需要一起分析时，可用数据模型建立关系，避免把每张表的属性都重复复制到订单中。</p><p>例如订单表每行是一条订单明细，产品表每个产品编码一行。产品表的编码必须唯一，订单表的编码可以重复，建立产品到订单的一对多关系。连接列的数据类型应一致；缺失产品编码、重复维度键和错误粒度都会影响分析结果。</p><p>在支持的 Windows 版本中，可通过加载到数据模型、数据关系或 Power Pivot 管理界面完成设置。Power Pivot 在不同产品中的可用范围不同，尤其不要把 Windows 的完整功能流程直接等同于 Mac。<a href="https://support.microsoft.com/en-us/excel/learn-to-use-power-query-and-power-pivot-in-excel" target="_blank" rel="noopener noreferrer">微软功能与平台说明</a></p><h2 id="dax" tabindex="-1">计算列与度量值 <a class="header-anchor" href="#dax" aria-label="Permalink to &quot;计算列与度量值 {#dax}&quot;">​</a></h2><p>计算列为每行保存结果，例如数量乘单价；度量值在当前透视表的筛选上下文中计算，例如“某部门、某月、某状态”的合计。DAX 与单元格公式不是同一套使用环境，不应把度量值直接粘到普通单元格。</p><p>下面是度量值的概念写法；如果对话框把名称和公式分开，名称填冒号前的内容，公式从等号开始：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>订单金额 := SUM(Sales[金额])</span></span>
<span class="line"><span>完成金额 := CALCULATE(SUM(Sales[金额]), Sales[状态] = &quot;已完成&quot;)</span></span></code></pre></div><p>第一个随当前筛选变化；第二个明确应用已完成状态条件，对同一状态字段已有筛选的行为要理解并验证。日期分析宜有连续的日期表并建立正确关系，不要只凭月份文字跨年度汇总。先用已知八条数据校验 5120、4060 和 3160，再处理真实大数据。</p><h2 id="goal-seek" tabindex="-1">单变量目标求解 <a class="header-anchor" href="#goal-seek" aria-label="Permalink to &quot;单变量目标求解 {#goal-seek}&quot;">​</a></h2><p>假设单价为 100、单位成本为 60、固定成本为 1000，希望利润达到 2000。新表 B2 输入单价，B3 输入单位成本，B4 输入固定成本，B5 输入数量，B6 输入：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=(B2-B3)*B5-B4</span></span></code></pre></div><p>在支持此功能的桌面版中，使用“数据 → 模拟分析 → 单变量求解”：目标单元格 B6，目标值 2000，可变单元格 B5。预期数量是 <strong>75</strong>，可手算 <code>(2000+1000)/(100-60)</code> 核对。</p><p>可变单元格必须影响目标公式。求解得到的数还要符合业务约束，例如数量必须整数、价格不可负；目标求解不负责完整约束优化，也不能保证所有模型都有唯一解。</p><h2 id="scenarios" tabindex="-1">比较多个方案 <a class="header-anchor" href="#scenarios" aria-label="Permalink to &quot;比较多个方案 {#scenarios}&quot;">​</a></h2><p>先建立一张明确的方案表，列出价格、数量、收入、成本和利润。每个方案用同样公式，比较时只改变已声明的输入。可使用模拟分析中的数据表分析一个或两个变量，注意它与 <code>Ctrl+T</code> 建立的 Excel 表格不是同一个功能。</p><p>涉及多变量和约束优化时可考虑规划求解加载项：定义目标、可变区域、上下界和整数条件，再选择适合模型的方法。不能只看“找到解”的提示，还需核对约束、单位、可执行性和不同初始值是否产生不同结果。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>把单位成本从 60 改为 70，同样利润目标下数量应为 100；当单价等于单位成本时，增加数量无法覆盖固定成本，不能用旧答案继续解释。记录模型假设“单价和单位成本固定、不考虑容量限制”，说明这些假设变化后结果为什么失效。</p><h2 id="walkthrough" tabindex="-1">图示跟做：反推达到利润目标所需的数量 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：反推达到利润目标所需的数量 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：建立一眼能核对的模型 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：建立一眼能核对的模型 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：工作表区域 → 单元格 B2:B6。</strong></p><p>在独立工作表 A2:A6 写单价、单位成本、固定成本、数量、利润，B2:B5 分别输入 100、60、1000、1。B6 输入 =(B2-B3)*B5-B4，初始利润应为 -960。先手动把数量改成 75，确认利润为 2000，然后改回 1。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：让 Excel 调整数量 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：让 Excel 调整数量 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：数据 → 单变量求解。</strong></p><p>在支持的桌面版选择“数据 → 模拟分析 → 单变量求解”。目标单元格选择利润公式 B6，目标值填 2000，可变单元格选 B5。完成后检查结果接近 75，并代回公式复算；目标格不能是一个写死的 2000，必须依赖可变单元格。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：改变假设再做敏感性检查 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：改变假设再做敏感性检查 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：数据 → 单变量求解。</strong></p><p>把单位成本 B3 改为 70，重新运行同一目标求解，数量应为 100。记录模型假设：单价、单位成本固定且未考虑产能限制。如果业务数量必须整数，应检查结果是否可执行；存在多变量、上下界或整数约束时，不能把一次目标求解当成完整优化方案。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>当单价等于单位成本时，每件毛利为零，增加数量不能覆盖固定成本。此时求解失败是模型约束导致的结果，不能强行沿用旧数量。</p>`,32))])}}});export{f as __pageData,g as default};
